import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel
} from '../primitives';
import { StepInfo } from './index';

// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

// Width chosen so step headers and the tied-weight pair fit without forcing
// excessive fitToView scaling. The layout is intentionally vertical-first to
// give each tensor room to breathe.
const W = 900;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e8f5e9', stroke: '#4caf50' },
  weight: { fill: '#f1f5f9', stroke: '#64748b' },
  project: { fill: '#e3f2fd', stroke: '#1976d2' },
  softmax: { fill: '#fff8e1', stroke: '#f9a825' },
  output: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  router: { fill: '#ede9fe', stroke: '#7c3aed' },
  expert: { fill: '#e0f2f1', stroke: '#009688' },
  mul: { fill: '#fff3e0', stroke: '#f57c00' },
  inset: { fill: '#f8fafc', stroke: '#cbd5e1' },
  text: 'var(--text)',
  muted: 'var(--text-muted)',
};

const STEP_GROUPS = {
  input: 'step-lm-head-input',
  project: 'step-lm-head-project',
  softmax: 'step-lm-head-softmax',
  output: 'step-lm-head-output',
};

const BOX_H = 76;
const BOX_W = 760;
const MAT_H = 90;
const VEC_H = 42;
const VEC_W = 170;
const WEIGHT_W = 150;
const WEIGHT_H = 110;
const SEQ_W = 190;
const GROUP_GAP = 86;
const BOX_TO_ROW_GAP = 44;
const VERTICAL_ARROW_LEN = 52;

// ═══════════════════════════════════════════════════════════════════════════════
// Step metadata
// ═══════════════════════════════════════════════════════════════════════════════

interface LmHeadStep extends StepInfo {}

const BASE_STEPS = {
  input: {
    id: 1,
    label: 'Input hidden states',
    shortLabel: 'Input',
    formula: 'h ∈ ℝ^(B×S×D)',
    explanation:
      'The LM head receives the final hidden states from the transformer stack, one vector per token position.',
    code: { title: 'Input', lines: ['h = transformer_output  # [B, S, D]'] },
    svgGroup: STEP_GROUPS.input,
    color: COLORS.input.stroke,
    fill: COLORS.input.fill,
  },
  project: {
    id: 2,
    label: 'Project to vocabulary space',
    shortLabel: 'Project',
    formula: 'logits = h · W_out',
    explanation:
      'A linear projection maps each hidden vector to a score for every token in the vocabulary.',
    code: {
      title: 'Projection',
      lines: [
        'self.lm_head = nn.Linear(d_model, vocab_size, bias=False)',
        'logits = self.lm_head(h)  # [B, S, V]',
      ],
    },
    svgGroup: STEP_GROUPS.project,
    color: COLORS.project.stroke,
    fill: COLORS.project.fill,
  },
  softmax: {
    id: 3,
    label: 'Softmax over vocabulary',
    shortLabel: 'Softmax',
    formula: 'probs = softmax(logits, dim=-1)',
    explanation:
      'Scores are normalized into a probability distribution over the vocabulary at each position.',
    code: { title: 'Softmax', lines: ['probs = F.softmax(logits, dim=-1)  # [B, S, V]'] },
    svgGroup: STEP_GROUPS.softmax,
    color: COLORS.softmax.stroke,
    fill: COLORS.softmax.fill,
  },
  output: {
    id: 4,
    label: 'Output probability distribution',
    shortLabel: 'Output',
    formula: 'probs ∈ ℝ^(B×S×V)',
    explanation:
      'The result is a probability vector per token position, ready for sampling or greedy decoding.',
    code: { title: 'Output', lines: ['return probs  # [B, S, V]'] },
    svgGroup: STEP_GROUPS.output,
    color: COLORS.output.stroke,
    fill: COLORS.output.fill,
  },
};

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - BOX_W / 2)
    .attr('y', y)
    .attr('width', BOX_W)
    .attr('height', BOX_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  grp.append('circle')
    .attr('cx', cx - BOX_W / 2 + 26)
    .attr('cy', y + BOX_H / 2)
    .attr('r', 15)
    .attr('fill', stroke);
  lbl(grp, cx - BOX_W / 2 + 26, y + BOX_H / 2 + 1, String(stepNum), { size: 14, weight: '700', color: '#fff' });

  lbl(grp, cx - BOX_W / 2 + 54, y + BOX_H / 2 - 1, title, {
    size: 16,
    weight: '600',
    color: 'var(--text)',
    anchor: 'start',
  });
  lbl(grp, cx + BOX_W / 2 - 18, y + BOX_H / 2 - 1, formula, {
    size: 12,
    color: 'var(--text-muted)',
    font: 'monospace',
    anchor: 'end',
  });
  return y + BOX_H;
}

function startGroup(_g: Gsel, className: string, step: number): Gsel {
  return _g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle')
    .attr('cx', cx)
    .attr('cy', cy)
    .attr('r', 17)
    .attr('fill', '#fff')
    .attr('stroke', color)
    .attr('stroke-width', 2);
  lbl(g, cx, cy, text, { size: 13, weight: '700', color });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers (center-based)
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimTop: 'S',
    dimRight: 'D',
  });
}

function drawOutputMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.project.fill,
  stroke = COLORS.project.stroke
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width: 250,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 14,
    rows: 1,
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke,
  width = WEIGHT_W,
  height = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, x, cy - height / 2, {
    width,
    height,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 6,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
}

function drawWideVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width: number
): void {
  drawMatrixBlock(g as Sel, x, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 12,
    rows: 1,
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter summary
// ═══════════════════════════════════════════════════════════════════════════════

function drawParamSummary(
  g: Gsel,
  cx: number,
  y: number,
  dModel: number,
  seqLen: number,
  vocabSize: number,
  variant: string
): number {
  const SUM_W = 840;
  const SUM_H = 76;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect')
    .attr('width', SUM_W)
    .attr('height', SUM_H)
    .attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);
  lbl(grp, 16, 24, 'Parameters →', { size: 11, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model = ${dModel}`, dim: 'hidden dim', color: '#4caf50' },
    { label: `seq_len = ${seqLen}`, dim: 'tokens', color: '#1976d2' },
    { label: `vocab_size = ${fmtNum(vocabSize)}`, dim: 'output dim', color: '#7b1fa2' },
    { label: `variant = ${variant.replace(/-/g, ' ')}`, dim: 'head type', color: '#f57c00' },
  ];
  const itemW = 206;
  const startX = 16;
  items.forEach((item, i) => {
    const px = startX + i * itemW;
    grp.append('rect')
      .attr('x', px)
      .attr('y', 32)
      .attr('width', itemW - 8)
      .attr('height', 36)
      .attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08))
      .attr('stroke', item.color)
      .attr('stroke-width', 1);
    lbl(grp, px + 10, 52, item.label, {
      size: 11,
      weight: '600',
      color: item.color,
      font: 'monospace',
      anchor: 'start',
    });
    lbl(grp, px + 10, 64, `→ ${item.dim}`, { size: 9, color: item.color, anchor: 'start' });
  });
  return y + SUM_H + 16;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Shared Softmax / Output steps
// ═══════════════════════════════════════════════════════════════════════════════

function drawSoftmaxStep(g: Gsel, cx: number, y: number, vocabSize: number): number {
  const stepGrp = startGroup(g, STEP_GROUPS.softmax, 3);
  const headerBottom = stepHeader(
    stepGrp,
    cx,
    y,
    3,
    'Softmax over vocabulary',
    'probs = softmax(logits, dim=-1)',
    COLORS.softmax.fill,
    COLORS.softmax.stroke
  );

  const logitsX = cx - 150;
  const probsX = cx + 30;
  const vecCy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;

  drawWideVector(
    stepGrp,
    logitsX,
    vecCy,
    'logits',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.project.fill,
    COLORS.project.stroke,
    180
  );

  const badgeW = 92;
  const badgeCy = vecCy;
  const badgeX = cx - badgeW / 2;
  stepGrp
    .append('rect')
    .attr('x', badgeX)
    .attr('y', badgeCy - VEC_H / 2)
    .attr('width', badgeW)
    .attr('height', VEC_H)
    .attr('rx', 6)
    .attr('fill', COLORS.softmax.fill)
    .attr('stroke', COLORS.softmax.stroke)
    .attr('stroke-width', 1.5);
  lbl(stepGrp, cx, badgeCy, 'softmax', { size: 12, weight: '600', color: COLORS.softmax.stroke });
  arrowH(stepGrp, logitsX + 180, badgeX, vecCy, COLORS.project.stroke);

  drawWideVector(
    stepGrp,
    probsX,
    vecCy,
    'probs',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.output.fill,
    COLORS.output.stroke,
    180
  );
  arrowH(stepGrp, badgeX + badgeW, probsX, vecCy, COLORS.softmax.stroke);

  // highlight one position to show a probability peak
  const cellW = 178 / 12;
  const pad = 2;
  const c = 3;
  stepGrp
    .append('rect')
    .attr('x', probsX + 1 + c * cellW + pad)
    .attr('y', vecCy - VEC_H / 2 + 1 + pad)
    .attr('width', cellW - pad * 2)
    .attr('height', VEC_H - 2 - pad * 2)
    .attr('rx', 2)
    .attr('fill', COLORS.output.stroke)
    .attr('opacity', 0.35)
    .attr('stroke', COLORS.output.stroke)
    .attr('stroke-width', 1);

  lbl(stepGrp, cx, vecCy + VEC_H / 2 + 24, 'each row sums to 1.0 over vocab', { size: 12, color: COLORS.muted });

  return vecCy + VEC_H / 2 + 42;
}

function drawOutputStep(g: Gsel, cx: number, y: number, vocabSize: number): number {
  const stepGrp = startGroup(g, STEP_GROUPS.output, 4);
  const headerBottom = stepHeader(
    stepGrp,
    cx,
    y,
    4,
    'Output probability distribution',
    `probs ∈ ℝ^(B×S×${fmtNum(vocabSize)})`,
    COLORS.output.fill,
    COLORS.output.stroke
  );
  const matCy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawOutputMatrix(
    stepGrp,
    cx - 125,
    matCy,
    'probs',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.output.fill,
    COLORS.output.stroke
  );
  lbl(stepGrp, cx, matCy + VEC_H / 2 + 22, 'passed to decoding strategy (greedy / sampling)', {
    size: 12,
    color: COLORS.muted,
  });
  return matCy + VEC_H / 2 + 40;
}

function drawInputStep(g: Gsel, cx: number, y: number): number {
  const stepGrp = startGroup(g, STEP_GROUPS.input, 1);
  const headerBottom = stepHeader(
    stepGrp,
    cx,
    y,
    1,
    'Input hidden states',
    'h ∈ ℝ^(B×S×D)',
    COLORS.input.fill,
    COLORS.input.stroke
  );
  const matCy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(stepGrp, cx - SEQ_W / 2, matCy, 'h', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(stepGrp, cx, matCy + MAT_H / 2 + 20, 'one hidden vector per token position', {
    size: 12,
    color: COLORS.muted,
  });
  return matCy + MAT_H / 2 + GROUP_GAP;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Compact per-token annotation
// ═══════════════════════════════════════════════════════════════════════════════

function drawPerTokenAnnotation(
  g: Gsel,
  cx: number,
  y: number,
  dModel: number,
  vocabSize: number,
  weightLabel: string
): number {
  const INSET_W = 560;
  const INSET_H = 78;
  const x = cx - INSET_W / 2;
  const grp = g.append('g');

  grp.append('rect')
    .attr('x', x)
    .attr('y', y)
    .attr('width', INSET_W)
    .attr('height', INSET_H)
    .attr('rx', 8)
    .attr('fill', COLORS.inset.fill)
    .attr('stroke', COLORS.inset.stroke)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '4 3');

  const cy = y + INSET_H / 2;
  const leftX = x + 30;
  const weightX = x + 165;
  const rightX = x + 360;
  const opX = x + 285;

  drawSmallVector(grp, leftX, cy, 'h_t', `[${dModel}]`, COLORS.input.fill, COLORS.input.stroke, 100);
  drawWeightMatrix(grp, weightX, cy, weightLabel, `[D, ${fmtNum(vocabSize)}]`, COLORS.weight.fill, COLORS.weight.stroke, 100, 72);
  drawSmallVector(grp, rightX, cy, 'logits_t', `[${fmtNum(vocabSize)}]`, COLORS.project.fill, COLORS.project.stroke, 120);

  opCircle(grp, opX, cy, '@', '#64748b');
  arrowH(grp, leftX + 100, opX - 18, cy, COLORS.input.stroke);
  arrowH(grp, weightX + 100, opX - 18, cy, COLORS.weight.stroke);
  arrowH(grp, opX + 18, rightX, cy, COLORS.project.stroke);

  return y + INSET_H + 14;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

interface RenderResult {
  steps: LmHeadStep[];
  y: number;
}

function renderUntied(g: Gsel, cx: number, y: number, dModel: number, vocabSize: number): RenderResult {
  const steps: LmHeadStep[] = [];
  steps.push({ ...BASE_STEPS.input, id: 1 });
  y = drawInputStep(g, cx, y);

  steps.push({ ...BASE_STEPS.project, id: 2 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.project.stroke);
  const projGrp = startGroup(g, STEP_GROUPS.project, 2);
  const projHeaderBottom = stepHeader(
    projGrp,
    cx,
    y,
    2,
    'Untied projection',
    'logits = h · W_out',
    COLORS.project.fill,
    COLORS.project.stroke
  );

  // Vertical matmul: h [B,S,D] -> W_out [D,V] -> logits [B,S,V]
  let cy = projHeaderBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(projGrp, cx - SEQ_W / 2, cy, 'h', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke);
  lbl(projGrp, cx + SEQ_W / 2 + 16, cy, 'hidden states', { size: 11, color: COLORS.muted, anchor: 'start' });

  let arrowY = cy + MAT_H / 2;
  arrowDown(projGrp, cx, arrowY, arrowY + VERTICAL_ARROW_LEN, COLORS.project.stroke);
  cy = arrowY + VERTICAL_ARROW_LEN + WEIGHT_H / 2;
  drawWeightMatrix(
    projGrp,
    cx - WEIGHT_W / 2,
    cy,
    'W_out',
    `[D, ${fmtNum(vocabSize)}]`,
    COLORS.weight.fill,
    COLORS.weight.stroke,
    WEIGHT_W,
    WEIGHT_H
  );
  lbl(projGrp, cx + WEIGHT_W / 2 + 16, cy, 'output projection', { size: 11, color: COLORS.muted, anchor: 'start' });

  arrowY = cy + WEIGHT_H / 2;
  arrowDown(projGrp, cx, arrowY, arrowY + VERTICAL_ARROW_LEN, COLORS.project.stroke);
  cy = arrowY + VERTICAL_ARROW_LEN + VEC_H / 2;
  drawOutputMatrix(
    projGrp,
    cx - 125,
    cy,
    'logits',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.project.fill,
    COLORS.project.stroke
  );
  lbl(projGrp, cx + 127, cy, 'vocabulary scores', { size: 11, color: COLORS.muted, anchor: 'start' });

  lbl(
    projGrp,
    cx,
    cy + VEC_H / 2 + 28,
    `[B, S, ${dModel}] @ [${dModel}, ${fmtNum(vocabSize)}] → [B, S, ${fmtNum(vocabSize)}]`,
    { size: 12, color: COLORS.muted, font: 'monospace' }
  );

  y = cy + VEC_H / 2 + 48;

  // Compact per-token annotation
  y = drawPerTokenAnnotation(projGrp, cx, y, dModel, vocabSize, 'W_out');

  y += GROUP_GAP - 14;

  steps.push({ ...BASE_STEPS.softmax, id: 3 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.softmax.stroke);
  const softmaxBottom = drawSoftmaxStep(g, cx, y, vocabSize);
  y = softmaxBottom + GROUP_GAP;

  steps.push({ ...BASE_STEPS.output, id: 4 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outputBottom = drawOutputStep(g, cx, y, vocabSize);
  y = outputBottom + GROUP_GAP;

  return { steps, y };
}

function renderTied(g: Gsel, cx: number, y: number, dModel: number, vocabSize: number): RenderResult {
  const steps: LmHeadStep[] = [];
  steps.push({
    ...BASE_STEPS.input,
    id: 1,
    explanation: 'The LM head receives the final hidden states. Tied weights reuse the input embedding matrix.',
  });
  y = drawInputStep(g, cx, y);

  steps.push({
    ...BASE_STEPS.project,
    id: 2,
    label: 'Tied projection: reuse embedding matrix',
    shortLabel: 'Tied Project',
    formula: 'logits = h · Eᵀ',
    explanation:
      'The output projection shares its weights with the input embedding matrix transposed, saving d_model × vocab_size parameters.',
    code: {
      title: 'Tied projection',
      lines: [
        'self.lm_head.weight = self.embed.weight  # E [V, D]',
        'logits = self.lm_head(h)                 # uses Eᵀ [D, V]',
      ],
    },
  });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.project.stroke);
  const projGrp = startGroup(g, STEP_GROUPS.project, 2);
  const projHeaderBottom = stepHeader(
    projGrp,
    cx,
    y,
    2,
    'Tied projection',
    'logits = h · Eᵀ',
    COLORS.project.fill,
    COLORS.project.stroke
  );

  // E [V, D] -> transpose -> E^T [D, V]
  let cy = projHeaderBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  drawWeightMatrix(
    projGrp,
    cx - WEIGHT_W / 2,
    cy,
    'E',
    `[${fmtNum(vocabSize)}, ${dModel}]`,
    COLORS.input.fill,
    COLORS.input.stroke,
    WEIGHT_W,
    WEIGHT_H
  );
  lbl(projGrp, cx + WEIGHT_W / 2 + 16, cy, 'input embedding matrix', {
    size: 11,
    color: COLORS.muted,
    anchor: 'start',
  });

  let arrowY = cy + WEIGHT_H / 2;
  arrowDown(projGrp, cx, arrowY, arrowY + VERTICAL_ARROW_LEN, COLORS.project.stroke);

  const transposeCy = arrowY + VERTICAL_ARROW_LEN + VEC_H / 2;
  const badgeW = 110;
  projGrp
    .append('rect')
    .attr('x', cx - badgeW / 2)
    .attr('y', transposeCy - VEC_H / 2)
    .attr('width', badgeW)
    .attr('height', VEC_H)
    .attr('rx', 6)
    .attr('fill', COLORS.softmax.fill)
    .attr('stroke', COLORS.softmax.stroke)
    .attr('stroke-width', 1.5);
  lbl(projGrp, cx, transposeCy, 'transpose', { size: 12, weight: '600', color: COLORS.softmax.stroke });
  lbl(
    projGrp,
    cx,
    transposeCy + VEC_H / 2 + 20,
    `E [${fmtNum(vocabSize)}, ${dModel}]  →  Eᵀ [${dModel}, ${fmtNum(vocabSize)}]`,
    { size: 12, color: COLORS.muted, font: 'monospace' }
  );

  arrowY = transposeCy + VEC_H / 2 + 20 + 16;
  arrowDown(projGrp, cx, arrowY - 16, arrowY, COLORS.project.stroke);
  cy = arrowY + WEIGHT_H / 2;
  drawWeightMatrix(
    projGrp,
    cx - WEIGHT_W / 2,
    cy,
    'Eᵀ',
    `[${dModel}, ${fmtNum(vocabSize)}]`,
    COLORS.project.fill,
    COLORS.project.stroke,
    WEIGHT_W,
    WEIGHT_H
  );
  lbl(projGrp, cx + WEIGHT_W / 2 + 16, cy, 'output projection = Eᵀ', {
    size: 11,
    color: COLORS.muted,
    anchor: 'start',
  });

  arrowY = cy + WEIGHT_H / 2;
  arrowDown(projGrp, cx, arrowY, arrowY + VERTICAL_ARROW_LEN, COLORS.project.stroke);
  cy = arrowY + VERTICAL_ARROW_LEN + VEC_H / 2;
  drawOutputMatrix(
    projGrp,
    cx - 125,
    cy,
    'logits',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.project.fill,
    COLORS.project.stroke
  );

  lbl(
    projGrp,
    cx,
    cy + VEC_H / 2 + 28,
    `[B, S, ${dModel}] @ [${dModel}, ${fmtNum(vocabSize)}] → [B, S, ${fmtNum(vocabSize)}]`,
    { size: 12, color: COLORS.muted, font: 'monospace' }
  );

  y = cy + VEC_H / 2 + 48;

  y = drawPerTokenAnnotation(projGrp, cx, y, dModel, vocabSize, 'Eᵀ');

  y += GROUP_GAP - 14;

  steps.push({ ...BASE_STEPS.softmax, id: 3 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.softmax.stroke);
  const softmaxBottom = drawSoftmaxStep(g, cx, y, vocabSize);
  y = softmaxBottom + GROUP_GAP;

  steps.push({ ...BASE_STEPS.output, id: 4 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outputBottom = drawOutputStep(g, cx, y, vocabSize);
  y = outputBottom + GROUP_GAP;

  return { steps, y };
}

function renderMoeHead(
  g: Gsel,
  cx: number,
  y: number,
  _dModel: number,
  vocabSize: number,
  _seqLen: number
): RenderResult {
  const steps: LmHeadStep[] = [];
  const numExperts = 4;
  const shardSize = Math.ceil(vocabSize / numExperts);

  steps.push({
    ...BASE_STEPS.input,
    id: 1,
    explanation: 'The MoE head receives hidden states and routes them to a set of vocabulary experts.',
  });
  y = drawInputStep(g, cx, y);

  steps.push({
    ...BASE_STEPS.project,
    id: 2,
    label: 'MoE head: route + expert projections',
    shortLabel: 'MoE Project',
    formula: 'logits = concat_e(h · W_e) ⊙ router(h)',
    explanation:
      'A router decides how much to weight each expert head. Each expert projects to a vocabulary shard; ' +
      'their outputs are concatenated back to full vocab size and gated by the router weights.',
    code: {
      title: 'MoE head',
      lines: [
        'self.router = nn.Linear(d_model, n_experts)',
        'self.experts = nn.ModuleList([nn.Linear(d_model, vocab_size // n_experts) for _ in range(n_experts)])',
        'r = F.softmax(self.router(h), dim=-1)          # [B, S, E]',
        'all = torch.cat([e(h) for e in self.experts], dim=-1)  # [B, S, V]',
        'logits = all * r.unsqueeze(-1)                 # broadcast gate over vocab shards',
      ],
    },
  });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.project.stroke);
  const projGrp = startGroup(g, STEP_GROUPS.project, 2);
  const projHeaderBottom = stepHeader(
    projGrp,
    cx,
    y,
    2,
    'MoE head projection',
    'logits = concat_e(h·W_e) ⊙ router(h)',
    COLORS.project.fill,
    COLORS.project.stroke
  );

  // Router row
  const routerRowCy = projHeaderBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  const routerLeftX = cx - 270;
  const routerWeightX = cx - 95;
  const routerLogitsX = cx + 75;
  const routerProbsX = cx + 245;

  drawSmallVector(projGrp, routerLeftX, routerRowCy, 'h', '[B, S, D]', COLORS.input.fill, COLORS.input.stroke, 120);
  drawWeightMatrix(projGrp, routerWeightX, routerRowCy, 'W_router', `[D, ${numExperts}]`, COLORS.router.fill, COLORS.router.stroke, 110, 72);
  drawSmallVector(projGrp, routerLogitsX, routerRowCy, 'gate_logits', `[B, S, ${numExperts}]`, COLORS.router.fill, COLORS.router.stroke, 120);

  const routerOpX = cx - 15;
  opCircle(projGrp, routerOpX, routerRowCy, '@', '#64748b');
  arrowH(projGrp, routerLeftX + 120, routerOpX - 18, routerRowCy, COLORS.input.stroke);
  arrowH(projGrp, routerWeightX + 110, routerOpX - 18, routerRowCy, COLORS.router.stroke);
  arrowH(projGrp, routerOpX + 18, routerLogitsX, routerRowCy, COLORS.router.stroke);

  const routerSoftmaxBadgeW = 92;
  const routerSoftmaxBadgeX = routerLogitsX + 120 + 12;
  projGrp
    .append('rect')
    .attr('x', routerSoftmaxBadgeX)
    .attr('y', routerRowCy - VEC_H / 2)
    .attr('width', routerSoftmaxBadgeW)
    .attr('height', VEC_H)
    .attr('rx', 6)
    .attr('fill', COLORS.softmax.fill)
    .attr('stroke', COLORS.softmax.stroke)
    .attr('stroke-width', 1.5);
  lbl(projGrp, routerSoftmaxBadgeX + routerSoftmaxBadgeW / 2, routerRowCy, 'softmax', {
    size: 10,
    weight: '600',
    color: COLORS.softmax.stroke,
  });
  arrowH(projGrp, routerLogitsX + 120, routerSoftmaxBadgeX, routerRowCy, COLORS.router.stroke);
  drawSmallVector(projGrp, routerProbsX, routerRowCy, 'router_probs', `[B, S, ${numExperts}]`, COLORS.router.fill, COLORS.router.stroke, 120);
  arrowH(projGrp, routerSoftmaxBadgeX + routerSoftmaxBadgeW, routerProbsX, routerRowCy, COLORS.softmax.stroke);
  lbl(projGrp, cx, routerRowCy + VEC_H / 2 + 24, `router(h) → softmax → ${numExperts} expert weights per token`, {
    size: 12,
    color: COLORS.muted,
  });

  // Fan-out line from h to expert grid
  const fanY = routerRowCy + VEC_H / 2 + 38;
  arrowDown(projGrp, cx, routerRowCy + VEC_H / 2 + 10, fanY, COLORS.input.stroke);
  lbl(projGrp, cx + 12, (routerRowCy + VEC_H / 2 + 10 + fanY) / 2, 'h', {
    size: 11,
    color: COLORS.input.stroke,
    anchor: 'start',
  });

  // Expert grid (2 x 2) with generous spacing
  const boxW = 220;
  const boxH = 132;
  const hGap = 36;
  const vGap = 32;
  const gridW = boxW * 2 + hGap;
  const gridH = boxH * 2 + vGap;
  const gridTopY = fanY + 22;
  const gridLeftX = cx - gridW / 2;

  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
      const i = r * 2 + c;
      const x = gridLeftX + c * (boxW + hGap);
      const ey = gridTopY + r * (boxH + vGap);
      const eg = projGrp.append('g');

      eg.append('rect')
        .attr('x', x)
        .attr('y', ey)
        .attr('width', boxW)
        .attr('height', boxH)
        .attr('rx', 10)
        .attr('fill', COLORS.expert.fill)
        .attr('stroke', COLORS.expert.stroke)
        .attr('stroke-width', 1.5);

      lbl(eg, x + boxW / 2, ey + 20, `Expert ${i + 1}`, { size: 14, weight: '600', color: COLORS.expert.stroke });

      const matW = 150;
      const matH = 46;
      drawMatrixBlock(eg as Sel, x + (boxW - matW) / 2, ey + 36, {
        width: matW,
        height: matH,
        label: `W_${i + 1}`,
        sublabel: `[D, ${fmtNum(shardSize)}]`,
        fill: COLORS.weight.fill,
        stroke: COLORS.weight.stroke,
        cols: 5,
        rows: 3,
      });

      const outVecW = 170;
      drawSmallVector(eg, x + (boxW - outVecW) / 2, ey + 104, `logits_${i + 1}`, `[B, S, ${fmtNum(shardSize)}]`, COLORS.expert.fill, COLORS.expert.stroke, outVecW);

      // arrow from fan-out line to this expert
      const targetX = x + boxW / 2;
      const targetY = ey;
      drawArrow(g as Sel, targetX, fanY, targetX, targetY, { color: COLORS.input.stroke });
    }
  }

  // Concatenation
  const concatCy = gridTopY + gridH + 40;
  const concatX = cx - 90;
  drawWideVector(
    projGrp,
    concatX,
    concatCy,
    'all_logits',
    `[B, S, ${fmtNum(vocabSize)}]`,
    COLORS.project.fill,
    COLORS.project.stroke,
    180
  );

  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 2; c++) {
      const x = gridLeftX + c * (boxW + hGap) + boxW / 2;
      const ey = gridTopY + r * (boxH + vGap) + boxH;
      drawArrow(g as Sel, x, ey, concatX + 90, concatCy - VEC_H / 2, { color: COLORS.expert.stroke });
    }
  }
  lbl(projGrp, cx, concatCy + VEC_H / 2 + 20, `concatenate ${numExperts} shards → full vocab`, {
    size: 12,
    color: COLORS.muted,
  });

  // Gating multiply
  const gateCy = concatCy + VEC_H / 2 + 78;
  const gateLeftX = cx - 210;
  const gateRightX = cx + 30;
  drawWideVector(projGrp, gateLeftX, gateCy, 'all_logits', `[B, S, V]`, COLORS.project.fill, COLORS.project.stroke, 180);

  // router_probs comes from the router row and gates the logits
  const routerProbsGateX = cx + 160;
  const routerProbsGateY = gateCy - 64;
  drawSmallVector(
    projGrp,
    routerProbsGateX,
    routerProbsGateY,
    'router_probs',
    `[B, S, ${numExperts}]`,
    COLORS.router.fill,
    COLORS.router.stroke,
    120
  );
  arrowDown(projGrp, routerProbsGateX, routerProbsGateY + VEC_H / 2, gateCy - 18, COLORS.router.stroke);
  lbl(projGrp, routerProbsGateX + 66, routerProbsGateY - 4, 'broadcast over vocab shards', {
    size: 10,
    color: COLORS.router.stroke,
    anchor: 'start',
  });

  opCircle(projGrp, cx - 10, gateCy, '⊙', COLORS.mul.stroke);
  arrowH(projGrp, gateLeftX + 180, cx - 10 - 18, gateCy, COLORS.project.stroke);
  drawWideVector(projGrp, gateRightX, gateCy, 'gated_logits', `[B, S, V]`, COLORS.project.fill, COLORS.project.stroke, 180);
  arrowH(projGrp, cx - 10 + 18, gateRightX, gateCy, COLORS.mul.stroke);
  lbl(projGrp, cx, gateCy + VEC_H / 2 + 22, 'router weight scales each expert shard', {
    size: 12,
    color: COLORS.muted,
  });

  y = gateCy + VEC_H / 2 + GROUP_GAP;

  steps.push({ ...BASE_STEPS.softmax, id: 3 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.softmax.stroke);
  const softmaxBottom = drawSoftmaxStep(g, cx, y, vocabSize);
  y = softmaxBottom + GROUP_GAP;

  steps.push({ ...BASE_STEPS.output, id: 4 });
  arrowDown(g, cx, y - GROUP_GAP, y, COLORS.output.stroke);
  const outputBottom = drawOutputStep(g, cx, y, vocabSize);
  y = outputBottom + GROUP_GAP;

  return { steps, y };
}

