export function renderLmHeadDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 128;
  const vocabSize = Number(params.vocab_size) || 32000;
  const variant = String(params.variant || 'untied');

  const root = g as unknown as Gsel;
  let y = 32;

  // Title
  lbl(root, CX, y, 'Language Modeling Head', { size: 20, weight: '700', color: COLORS.text });
  y += 24;
  lbl(
    root,
    CX,
    y,
    `${variant.replace(/-/g, ' ')} head  ·  d_model=${dModel}  seq_len=${seqLen}  vocab_size=${fmtNum(vocabSize)}`,
    {
      size: 12,
      color: COLORS.muted,
    }
  );
  y += 32;

  // Param summary
  y = drawParamSummary(root, CX, y, dModel, seqLen, vocabSize, variant);
  y += 20;

  // Variant-specific diagram
  let result: RenderResult;
  switch (variant) {
    case 'tied':
      result = renderTied(root, CX, y, dModel, vocabSize);
      break;
    case 'moe_head':
      result = renderMoeHead(root, CX, y, dModel, vocabSize, seqLen);
      break;
    case 'untied':
    default:
      result = renderUntied(root, CX, y, dModel, vocabSize);
      break;
  }

  let footerY = result.y + 20;

  // Footer param / FLOP summary
  let paramsCount = 0;
  let flopsPerToken = 0;
  switch (variant) {
    case 'tied':
      paramsCount = 0;
      flopsPerToken = 2 * dModel * vocabSize;
      break;
    case 'moe_head': {
      const numExperts = 4;
      const shardSize = Math.ceil(vocabSize / numExperts);
      paramsCount = dModel * numExperts + numExperts * dModel * shardSize;
      flopsPerToken = 2 * dModel * vocabSize + 2 * dModel * numExperts;
      break;
    }
    case 'untied':
    default:
      paramsCount = dModel * vocabSize;
      flopsPerToken = 2 * dModel * vocabSize;
      break;
  }

  const summaryText =
    variant === 'tied'
      ? `Tied head reuses embedding params · ~${fmtNum(flopsPerToken)} FLOP/token`
      : `Params: ${fmtNum(paramsCount)} · ~${fmtNum(flopsPerToken)} FLOP/token`;
  const summaryGrp = root.append('g');
  lbl(summaryGrp, CX, footerY + 18, summaryText, { size: 12, color: COLORS.muted });
  footerY += 40;

  // Explanations
  const insightText =
    variant === 'tied'
      ? 'Tied weights share the output projection with the input embedding matrix. This saves d_model × vocab_size parameters and often improves training efficiency, though some models (PaLM, Gemma) untie for quality.'
      : variant === 'moe_head'
        ? 'MoE heads split the large vocabulary projection into smaller expert heads routed by a gating network. This can reduce active FLOPs if only a subset of experts is used, but adds routing complexity.'
        : 'The untied head learns a separate output projection W_out. It is the most flexible design but adds d_model × vocab_size parameters on top of the embedding matrix.';

  const perfText =
    variant === 'tied'
      ? `Projection cost is identical to untied (~${fmtNum(flopsPerToken)} FLOP/token), but memory is saved because W_out shares storage with E.`
      : variant === 'moe_head'
        ? `Total expert capacity ≈ d_model × vocab_size. The router adds ${fmtNum(dModel * 4)} params; active FLOPs depend on how many experts fire per token.`
        : `For Llama-2 7B this would be 4096 × 32000 ≈ 131M parameters. Softmax over the full vocabulary is computed only for positions that need a next-token distribution.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 12;

  // Cross-link
  const linkTarget = variant === 'moe_head' ? 'moe-router' : 'embedding';
  const linkLabel = variant === 'moe_head' ? 'View MoE Router ↗' : 'View Embedding ↗';
  drawComponentLink(g, CX - 80, footerY, 160, 32, linkTarget, linkLabel, {
    fill: '#e3f2fd',
    stroke: '#1976d2',
  });
  footerY += 50;

  // Code annotation
  const codeLines = buildCodeLines(variant, dModel, vocabSize);
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    `Language Modeling Head — ${variant.replace(/-/g, ' ').toUpperCase()}`,
    [summaryText],
    codeLines
  );

  return { width: W, height: footerY + 28, steps: result.steps };
}

function buildCodeLines(variant: string, dModel: number, vocabSize: number): string[] {
  switch (variant) {
    case 'tied':
      return [
        'self.embed = nn.Embedding(vocab_size, d_model)',
        'self.lm_head = nn.Linear(d_model, vocab_size, bias=False)',
        'self.lm_head.weight = self.embed.weight  # W_out = Eᵀ',
        '',
        'def forward(self, h):',
        '    logits = self.lm_head(h)  # [B, S, V]',
        '    return F.softmax(logits, dim=-1)',
      ];
    case 'moe_head':
      return [
        'n_experts = 4',
        'shard = vocab_size // n_experts',
        'self.router = nn.Linear(d_model, n_experts)',
        'self.experts = nn.ModuleList([',
        '    nn.Linear(d_model, shard) for _ in range(n_experts)',
        '])',
        '',
        'def forward(self, h):',
        '    r = F.softmax(self.router(h), dim=-1)        # [B, S, E]',
        '    all_logits = torch.cat([e(h) for e in self.experts], dim=-1)  # [B, S, V]',
        '    logits = all_logits * r.unsqueeze(-1)        # broadcast gate',
        '    return F.softmax(logits, dim=-1)',
      ];
    case 'untied':
    default:
      return [
        `self.lm_head = nn.Linear(${dModel}, ${vocabSize}, bias=False)`,
        '',
        'def forward(self, h):',
        '    logits = self.lm_head(h)  # [B, S, V]',
        '    return F.softmax(logits, dim=-1)',
      ];
  }
}
